type WorkContextBinding = {
  version: 1;
  id: string;
  status: "active" | "superseded";
  host: string;
  session_id: string;
  bound_at: string;
  last_seen_at: string;
  expires_at: string;
  collaboration_space: WorkspaceRef;
  provenance: {
    kind: "host_lifecycle" | "operator_rebind";
    lifecycle: string;
    observed_cwd: string;
  };
  superseded_by?: string;
  superseded_at?: string;
};

{
  "name": "anvil-redux",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=22.18.0"
  },
  "bin": {
    "anvil": "./bin/anvil.ts",
    "manifest": "./bin/manifest.ts",
    "brain": "./bin/brain.ts",
    "anvil-measurements": "./bin/anvil-measurements.ts"
  },
  "scripts": {
    "eval:brain-context": "node scripts/evaluate-brain-context.ts",
    "typecheck": "tsc --noEmit",
    "test": "npm run typecheck && node --test --test-concurrency=1 test/*.test.ts"
  },
  "devDependencies": {
    "@types/node": "^25.9.1",
    "js-tiktoken": "1.0.21",
    "typescript": "^6.0.3"
  },
  "dependencies": {
    "@modelcontextprotocol/client": "^2.0.0",
    "@modelcontextprotocol/server": "^2.0.0",
    "zod": "^4.4.3"
  }
}

import { spawn } from "node:child_process";
import { createHash, randomBytes, randomUUID } from "node:crypto";
import { constants as fsConstants } from "node:fs";
import {
  chmod,
  mkdir,
  open,
  readdir,
  readFile,
  rename,
  rm,
  stat,
} from "node:fs/promises";
import type { FileHandle } from "node:fs/promises";
import { join } from "node:path";
import { setTimeout as sleep } from "node:timers/promises";
import * as z from "zod/v4";

import {
  assertActiveWorkContextBinding,
  resolveWorkContextStateRoot,
